-- =====================================================================
-- 0006_ritual_tapetinho.sql
-- BodyMy — Troca o programa principal para "Protocolo 28 Dias — Ritual do Tapetinho".
--
-- GERADO automaticamente por scripts/gen-ritual-tapetinho-migration.ts a partir de
-- supabase/content/ritual-do-tapetinho.ts. NÃO edite à mão — regenere.
--
-- O QUE FAZ (idempotente — pode rodar mais de uma vez com segurança):
--   1. Localiza o produto base por qualquer slug conhecido do programa
--      ('ritual-do-tapetinho', 'pilates-somatico', 'caminhada-japonesa') — NÃO altera
--      kiwify_product_id nem kiwify_checkout_url, então os acessos ativos
--      continuam valendo, sem novo entitlement.
--   2. Atualiza nome, slug ('ritual-do-tapetinho'), descrição e sales_page do produto.
--   3. Desativa (ativo=false) o(s) programa(s) antigo(s) do produto —
--      o conteúdo anterior FICA no banco (reversível).
--   4. Cria/atualiza o programa 'ritual-do-tapetinho' e (re)insere as
--      28 aulas (4 semanas × 7 dias).
--   5. Mostra, ao final, a verificação (produto, programa antigo inativo,
--      programa novo ativo com 28 aulas).
--
-- NOTA sobre as alunas atuais: o entitlement é por product_id (inalterado),
-- então elas passam a ver o novo programa sem novo acesso. As
-- lesson_completions delas apontam para as aulas ANTIGAS (que permanecem no
-- banco, apenas em programa inativo), então o progresso no novo programa
-- começa em zero, sem erro. Check-ins e streak são independentes de programa
-- e ficam intactos.
-- =====================================================================

do $migration$
declare
  v_product_id uuid;
  v_program_id uuid;
  v_week_id    uuid;
  v_day_id     uuid;
  v_weeks      jsonb := $weeks$[{"numero":1,"titulo":"Semana 1 — Reconhecendo o corpo","dias":[{"numero":1,"titulo":"Segunda","aula":{"titulo":"Chegando ao corpo","duracao":10,"conteudo":{"intro":"Bem-vinda! Hoje a gente não vai “fazer exercício” — vamos só chegar. Deitar, respirar e perceber o corpo que já está aqui. É a base de tudo o que vem pela frente.","blocos":[{"tipo":"aviso","titulo":"Antes de começar","conteudo":"Este conteúdo é educativo e de bem-estar — não substitui fisioterapia, médico ou profissional de saúde. Respeite sempre os seus limites: movimento é para dar alívio, nunca dor. Se sentir dor, tontura ou desconforto, pare e, se necessário, procure orientação profissional. Se você tem alguma condição de saúde, converse com seu médico antes de começar."},{"tipo":"texto","titulo":"Preparação","conteudo":"Deite de costas em um tapete, toalha ou na cama. Dobre os joelhos com os pés apoiados, na largura do quadril. Deixe os braços ao lado do corpo. Se for mais confortável, coloque uma almofada fina sob a cabeça."},{"tipo":"passo","titulo":"Sentindo o apoio","conteudo":"Como fazer: Feche os olhos e perceba os pontos do corpo que tocam o chão: a cabeça, as costas, o quadril, os pés. Não mude nada, só observe.\nRespiração: Respire pelo nariz, no seu ritmo natural, sem controlar.\nRepetições: 1 minuto observando.\nVocê deve sentir: o peso do corpo entregando ao apoio, como se afundasse um pouquinho.\n⚠️ Sinal de parar: nada aqui força — se a lombar incomodar, aproxime mais os pés do quadril."},{"tipo":"passo","titulo":"Respiração na barriga","conteudo":"Como fazer: Leve uma das mãos à barriga. Ao inspirar, deixe a barriga subir suavemente sob a mão; ao soltar o ar, deixe descer. Sem empurrar.\nRespiração: Inspire contando até 3, solte contando até 4.\nRepetições: 8 a 10 respirações lentas.\nVocê deve sentir: a barriga se movendo com o ar, e os ombros ficando mais pesados.\n⚠️ Sinal de parar: se ficar tonta ou ofegante, volte à respiração normal."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Fique mais um instante deitada, sentindo como o corpo está agora. Depois abra os olhos devagar. Pronto — você já começou."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Você não precisa “fazer bonito”. No somático, aparecer e sentir já é a prática inteira. O resto vem sozinho."}]}}},{"numero":2,"titulo":"Terça","aula":{"titulo":"A respiração que solta","duracao":12,"conteudo":{"intro":"Hoje unimos respiração e um micro-movimento dos ombros. Quando a respiração conduz, o corpo solta sem esforço.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deitada de costas, joelhos dobrados e pés apoiados. Braços ao lado do corpo, palmas para cima."},{"tipo":"passo","titulo":"Ombros que sobem e derretem","conteudo":"Como fazer: Na inspiração, leve suavemente os ombros na direção das orelhas (bem pouco). Na expiração, deixe-os “derreter” de volta, afastando das orelhas.\nRespiração: Inspire subindo os ombros, solte o ar descendo.\nRepetições: 6 vezes, sem pressa.\nVocê deve sentir: a diferença entre o ombro tenso (subindo) e o ombro solto (descendo).\n⚠️ Sinal de parar: faça pequeno — se o pescoço reclamar, diminua o movimento."},{"tipo":"passo","titulo":"Abrir o peito com o ar","conteudo":"Como fazer: Ao inspirar, deixe o peito se abrir levemente; ao soltar, deixe as costelas se fecharem como um leque. O movimento é interno, quase invisível.\nRespiração: Respiração lenta, guiando a abertura e o fechamento.\nRepetições: 8 respirações.\nVocê deve sentir: o peito ganhando espaço, e a respiração ficando mais fácil.\n⚠️ Sinal de parar: nada de arquear a lombar; o movimento é só das costelas."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Descanse os braços e sinta os ombros. Compare com o começo: costumam estar mais baixos e leves."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Repare quantas vezes no dia você segura o ar sem notar — em uma mensagem difícil, no trânsito. Soltar o ar já é soltar tensão."}]}}},{"numero":3,"titulo":"Quarta","aula":{"titulo":"Balanço da pelve","duracao":12,"conteudo":{"intro":"Um movimento pequeno e delicioso para a lombar: inclinar a bacia para frente e para trás, devagar, deixando a coluna acompanhar.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deitada de costas, joelhos dobrados, pés apoiados na largura do quadril. Mãos descansando na barriga ou ao lado do corpo."},{"tipo":"passo","titulo":"Báscula da pelve","conteudo":"Como fazer: Imagine a bacia como uma tigela com água. Incline-a levemente para trás (a lombar se aproxima do chão) e depois para frente (a lombar faz um pequeno arco). Movimento minúsculo e lento.\nRespiração: Solte o ar ao aproximar a lombar do chão; inspire ao voltar.\nRepetições: 8 a 10 balanços suaves.\nVocê deve sentir: a lombar “rolando” entre os dois pontos, sem esforço das pernas.\n⚠️ Sinal de parar: se aparecer qualquer fisgada, reduza a amplitude pela metade."},{"tipo":"passo","titulo":"Pausa e sentir","conteudo":"Como fazer: Pare no meio, na posição mais neutra e confortável. Só observe a lombar apoiada.\nRespiração: Três respirações lentas.\nRepetições: 30 segundos.\nVocê deve sentir: a região que antes estava travada um pouco mais macia.\n⚠️ Sinal de parar: nenhum — esta é só a pausa."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Estique as pernas devagar, uma de cada vez, e sinta a lombar. Menos rígida costuma ser a sensação."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"A lombar não gosta de ficar parada o dia todo. Este balanço cabe até na cama, antes de dormir."}]}}},{"numero":4,"titulo":"Quinta","aula":{"titulo":"Pausa consciente (prática leve)","duracao":10,"conteudo":{"intro":"Dia mais calmo. Nada de “fazer” — hoje é reconhecer o corpo inteiro com atenção. Prática leve também é constância, e mantém sua sequência viva.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deite confortável, de costas, pernas estendidas ou joelhos dobrados — o que for melhor para você. Cobertor se quiser aconchego."},{"tipo":"passo","titulo":"Varredura do corpo","conteudo":"Como fazer: Leve a atenção aos pés e suba lentamente: pernas, quadril, barriga, peito, mãos, ombros, pescoço, rosto. Em cada região, só perceba como ela está — sem mudar.\nRespiração: Respiração natural, tranquila.\nRepetições: Uma passagem completa, cerca de 5 minutos.\nVocê deve sentir: quais regiões estão soltas e quais pedem mais atenção.\n⚠️ Sinal de parar: se a mente dispersar, tudo bem — volte gentilmente para onde parou."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Fique deitada mais um minuto, sem fazer nada. Depois volte devagar."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Descansar com atenção é diferente de desligar na TV: aqui o corpo aprende a soltar. Isso é treino também."}]}}},{"numero":5,"titulo":"Sexta","aula":{"titulo":"Cabeça que roda","duracao":13,"conteudo":{"intro":"Vamos sentar e soltar o pescoço com um movimento lento de virar a cabeça. Muita tensão do dia mora aqui.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Sente numa cadeira firme, pés apoiados no chão, coluna longa e relaxada. Mãos nas coxas."},{"tipo":"passo","titulo":"Virar o olhar","conteudo":"Como fazer: Vire a cabeça lentamente para a direita, como se fosse olhar por cima do ombro, só até onde é confortável. Volte ao centro. Depois para a esquerda.\nRespiração: Solte o ar ao virar, inspire ao voltar ao centro.\nRepetições: 4 vezes para cada lado.\nVocê deve sentir: o pescoço deslizando, sem “travar” no fim do movimento.\n⚠️ Sinal de parar: não force para ver mais atrás; pare onde ainda é agradável."},{"tipo":"passo","titulo":"Orelha ao ombro","conteudo":"Como fazer: Incline a cabeça levando a orelha direita na direção do ombro direito (sem subir o ombro). Volte ao centro e troque de lado.\nRespiração: Expire ao inclinar, inspire ao voltar.\nRepetições: 3 vezes para cada lado.\nVocê deve sentir: um alongamento suave na lateral do pescoço.\n⚠️ Sinal de parar: se descer um formigamento no braço, volte imediatamente ao centro."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Volte o olhar ao centro, feche os olhos e sinta o pescoço. Costuma ficar mais leve e móvel."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"No celular, a cabeça pende para frente e o pescoço paga a conta. Este movimento é um bom “reset” no meio do dia."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Abrir e fechar","duracao":14,"conteudo":{"intro":"Hoje abrimos e fechamos os braços como um leque, sentada, deixando a respiração conduzir. Ajuda a soltar a parte de cima das costas.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Sentada na beira da cadeira, pés bem apoiados, coluna longa. Braços à frente na altura do peito, palmas se olhando."},{"tipo":"passo","titulo":"Leque dos braços","conteudo":"Como fazer: Ao inspirar, abra os braços para os lados, como se abrisse uma janela; sinta o peito abrir. Ao soltar, traga os braços de volta à frente, arredondando levemente as costas.\nRespiração: Inspire abrindo, expire fechando.\nRepetições: 6 vezes lentas.\nVocê deve sentir: o peito abrindo na inspiração e as costas se soltando no fechamento.\n⚠️ Sinal de parar: mantenha os ombros longe das orelhas; se subirem, faça menor."},{"tipo":"passo","titulo":"Auto-abraço","conteudo":"Como fazer: Na última vez, ao fechar, cruze os braços num abraço em você mesma, uma mão em cada ombro. Fique ali respirando.\nRespiração: Três respirações lentas dentro do abraço.\nRepetições: 30 segundos.\nVocê deve sentir: as costas entre as escápulas se abrindo com o ar.\n⚠️ Sinal de parar: nenhum — é acolhimento."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Solte os braços no colo. Perceba a parte de cima das costas mais espaçosa."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Passar o dia com os ombros “fechados” à frente do teclado encurta o peito. Abrir de vez em quando reequilibra."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"O corpo em repouso (prática leve)","duracao":12,"conteudo":{"intro":"Fechamos a semana com um movimento gostoso da coluna, sentada, no ritmo da respiração. Suave, restaurador — e conta como dia ativo.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Sentada na cadeira, pés apoiados, mãos nas coxas."},{"tipo":"passo","titulo":"Gato e vaca sentada","conteudo":"Como fazer: Ao inspirar, cresça pela coluna e abra levemente o peito para cima (vaca). Ao soltar, arredonde as costas, queixo em direção ao peito (gato). Bem lento.\nRespiração: Inspire abrindo, expire arredondando.\nRepetições: 8 ciclos.\nVocê deve sentir: a coluna se movendo vértebra por vértebra, como uma onda.\n⚠️ Sinal de parar: amplitude confortável; nada de forçar o pescoço no final."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Volte ao centro, coluna longa. Sinta a semana: você apareceu 7 dias. Isso é grande."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Se só teve tempo para 5 minutos hoje, valeu igual. Constância é aparecer, não durar muito."}]}}}]},{"numero":2,"titulo":"Semana 2 — Soltando tensão","dias":[{"numero":1,"titulo":"Segunda","aula":{"titulo":"Soltando os ombros","duracao":16,"conteudo":{"intro":"Vamos usar a pandiculação — aquele espreguiçar natural — para soltar os ombros de verdade: contrair de leve, sustentar e soltar bem devagar.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Sentada ou em pé, coluna longa, braços soltos ao lado do corpo."},{"tipo":"passo","titulo":"Espreguiçar dos ombros","conteudo":"Como fazer: Suba os dois ombros na direção das orelhas contraindo suavemente. Sustente 3 segundos sentindo a leve tensão. Agora solte MUITO devagar, deixando os ombros descerem além de onde começaram.\nRespiração: Inspire subindo, segure o ar no topo, solte o ar descendo lentamente.\nRepetições: 4 vezes.\nVocê deve sentir: a “descida” mais longa e solta do que a subida — esse é o segredo.\n⚠️ Sinal de parar: se o pescoço reclamar, contraia menos."},{"tipo":"passo","titulo":"Círculos de ombro","conteudo":"Como fazer: Desenhe círculos lentos com os ombros para trás: sobe, vai para trás, desce, volta. Grandes e sem pressa.\nRespiração: Respiração livre, contínua.\nRepetições: 5 círculos para trás.\nVocê deve sentir: a articulação do ombro “lubrificando”, cada volta mais fácil.\n⚠️ Sinal de parar: reduza o tamanho do círculo se houver estalos com desconforto."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Solte tudo e sinta os ombros pendendo. Aquele peso que você carregava sem notar costuma diminuir."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Pandiculação é o que o gato faz ao acordar. O corpo humano adora — a gente é que esqueceu de fazer."}]}}},{"numero":2,"titulo":"Terça","aula":{"titulo":"Pescoço livre","duracao":15,"conteudo":{"intro":"Hoje é dia de dar espaço ao pescoço com inclinações e uma rotação bem lenta. Delicadeza é a palavra.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Sentada, coluna longa, ombros soltos. Deixe uma mão descansar na coxa."},{"tipo":"passo","titulo":"Sim e não lentos","conteudo":"Como fazer: Faça um “sim” minúsculo com a cabeça (queixo desce e sobe pouquíssimo) por algumas vezes; depois um “não” lento, virando o olhar de um lado ao outro.\nRespiração: Respiração tranquila, sem prender.\nRepetições: 4 “sins” e 4 “nãos”, bem pequenos.\nVocê deve sentir: a base do crânio deslizando sobre o pescoço.\n⚠️ Sinal de parar: movimentos pequenos: aqui menos é mais."},{"tipo":"passo","titulo":"Meia-lua do queixo","conteudo":"Como fazer: Leve o queixo ao peito (sem forçar) e desenhe uma meia-lua levando o queixo de um ombro ao outro, passando pela frente. Nunca jogue a cabeça para trás.\nRespiração: Solte o ar durante o desenho da meia-lua.\nRepetições: 3 vezes para cada direção.\nVocê deve sentir: a nuca se abrindo e a frente do pescoço deslizando.\n⚠️ Sinal de parar: sem levar a cabeça para trás; se tonteia, pare."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Volte ao centro e feche os olhos. Sinta o pescoço com mais espaço para respirar."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Tensão no pescoço muitas vezes é a mandíbula apertada. Solte os dentes: deixe um vãozinho entre eles."}]}}},{"numero":3,"titulo":"Quarta","aula":{"titulo":"Gato e vaca no chão","duracao":18,"conteudo":{"intro":"O clássico da mobilidade da coluna, agora em quatro apoios. Uma onda que percorre as costas inteiras.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Fique de quatro apoios, mãos sob os ombros e joelhos sob o quadril, sobre o tapete. Use uma toalha dobrada sob os joelhos se incomodar."},{"tipo":"passo","titulo":"A onda da coluna","conteudo":"Como fazer: Ao inspirar, deixe a barriga descer e o peito e o olhar subirem levemente (vaca). Ao soltar, empurre o chão e arredonde as costas para o teto, queixo ao peito (gato).\nRespiração: Inspire na vaca, expire no gato.\nRepetições: 8 a 10 ciclos lentos.\nVocê deve sentir: cada vértebra participando, do cóccix à nuca.\n⚠️ Sinal de parar: se os punhos incomodarem, apoie nos antebraços ou reduza o tempo."},{"tipo":"passo","titulo":"Descanso da criança","conteudo":"Como fazer: Leve o quadril na direção dos calcanhares e deite o tronco à frente, braços estendidos ou ao lado do corpo. Testa apoiada.\nRespiração: Respire para dentro das costas, sentindo-as subir.\nRepetições: 5 respirações.\nVocê deve sentir: as costas se abrindo a cada inspiração.\n⚠️ Sinal de parar: se os joelhos reclamarem, afaste-os ou coloque uma almofada atrás deles."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Volte devagar para sentada sobre os calcanhares ou de lado. Sinta a coluna mais fluida."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"A coluna tem umas 30 peças que adoram se mover juntas. Ela foi feita para ondular, não para ficar reta o dia todo."}]}}},{"numero":4,"titulo":"Quinta","aula":{"titulo":"Respirar e soltar (prática leve)","duracao":15,"conteudo":{"intro":"Dia restaurativo com as pernas apoiadas para descansar a lombar e as pernas cansadas. Pouco movimento, muito alívio.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deite de costas perto de uma parede ou de uma cadeira. Coloque as panturrilhas sobre o assento da cadeira (joelhos dobrados a 90°) ou as pernas apoiadas na parede, o que for confortável."},{"tipo":"passo","titulo":"Pernas em repouso","conteudo":"Como fazer: Com as pernas apoiadas, deixe a lombar relaxar no chão. Não faça nada com as pernas — só descanse o peso delas no apoio.\nRespiração: Respiração longa e lenta, expiração mais demorada que a inspiração.\nRepetições: 3 a 4 minutos.\nVocê deve sentir: a lombar e as pernas “desligando”, ficando pesadas.\n⚠️ Sinal de parar: se formigar demais, tire as pernas do apoio e estique no chão."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Role para o lado, fique um instante, e levante-se sem pressa. Pernas mais leves é a sensação comum."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Passou o dia em pé ou sentada? Cinco minutos com as pernas apoiadas fazem mais pela sua disposição do que parece."}]}}},{"numero":5,"titulo":"Sexta","aula":{"titulo":"Quadril que abre","duracao":18,"conteudo":{"intro":"O quadril guarda muita tensão de quem passa horas sentada. Vamos soltá-lo com movimentos lentos, deitada.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deitada de costas, joelhos dobrados, pés apoiados na largura do quadril."},{"tipo":"passo","titulo":"Joelhos que balançam","conteudo":"Como fazer: Com os pés um pouco mais afastados, deixe os dois joelhos caírem suavemente para a direita e depois para a esquerda, como limpadores de para-brisa lentos.\nRespiração: Solte o ar ao levar os joelhos para o lado, inspire ao voltar ao centro.\nRepetições: 6 vezes para cada lado.\nVocê deve sentir: o quadril e a lombar girando com leveza.\n⚠️ Sinal de parar: amplitude pequena; não force os joelhos ao chão."},{"tipo":"passo","titulo":"Abrir um joelho","conteudo":"Como fazer: Mantenha um pé apoiado e deixe o outro joelho abrir para o lado (como um livro abrindo), só até onde é confortável. Volte e troque de perna.\nRespiração: Expire ao abrir, inspire ao fechar.\nRepetições: 4 vezes para cada perna.\nVocê deve sentir: a virilha e a parte interna da coxa se abrindo suavemente.\n⚠️ Sinal de parar: se puxar a virilha com desconforto, abra menos."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Abrace os joelhos no peito por alguns segundos, se for confortável, e depois estique as pernas. Quadril mais livre."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Quadril preso costuma sobrecarregar a lombar. Soltar o quadril é um presente indireto para as suas costas."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Lombar que descansa","duracao":17,"conteudo":{"intro":"Foco carinhoso na lombar hoje: balanço da pelve mais amplo e um abraço de joelhos que costuma dar alívio imediato.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deitada de costas, joelhos dobrados, pés apoiados. Braços ao lado do corpo."},{"tipo":"passo","titulo":"Balanço amplo da pelve","conteudo":"Como fazer: Retome o balanço da pelve do Dia 3, agora deixando a onda subir um pouco mais pela coluna: ao aproximar a lombar do chão, deixe o cóccix subir levemente.\nRespiração: Solte o ar ao apoiar a lombar, inspire ao soltar.\nRepetições: 8 balanços.\nVocê deve sentir: a lombar massageando o chão de leve.\n⚠️ Sinal de parar: sem levantar o quadril alto; a onda é pequena."},{"tipo":"passo","titulo":"Abraço de joelhos","conteudo":"Como fazer: Traga um joelho de cada vez em direção ao peito e segure atrás das coxas (não sobre o joelho). Deixe a lombar afundar no chão.\nRespiração: Respire para dentro das costas, expiração longa.\nRepetições: 5 respirações; solte e repita 1 vez.\nVocê deve sentir: a lombar se abrindo e descansando no apoio.\n⚠️ Sinal de parar: se for muito para os dois joelhos, faça um de cada vez."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Devolva os pés ao chão, estique as pernas devagar e sinta a lombar mais quietinha."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Dor lombar leve muitas vezes melhora com movimento suave, não com repouso total. Mas dor forte ou que desce pela perna pede avaliação profissional."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"Torção suave (prática leve)","duracao":15,"conteudo":{"intro":"Fechamos a semana com uma torção restauradora deitada — daquelas que a coluna agradece. Movimento mínimo, alívio grande.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deitada de costas, joelhos dobrados e pés apoiados. Braços abertos em cruz, palmas para cima."},{"tipo":"passo","titulo":"Torção com os joelhos","conteudo":"Como fazer: Junte os joelhos e deixe-os cair devagar para um lado, enquanto o olhar vai para o lado oposto, se for confortável. Volte ao centro e troque.\nRespiração: Solte o ar ao girar, inspire ao voltar.\nRepetições: 3 a 4 vezes para cada lado, com pausa de uma respiração no fim.\nVocê deve sentir: uma torção gentil ao longo da coluna e do peito abrindo.\n⚠️ Sinal de parar: os ombros permanecem apoiados; se um levantar muito, gire menos."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Volte ao centro, abrace os joelhos por um instante e estique as pernas. Duas semanas concluídas — seu corpo já reconhece a prática."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Reparou como já entende melhor os sinais do corpo do que no Dia 1? Essa escuta é o verdadeiro resultado."}]}}}]},{"numero":3,"titulo":"Semana 3 — Movimento integrado","dias":[{"numero":1,"titulo":"Segunda","aula":{"titulo":"Do chão ao pé","duracao":20,"conteudo":{"intro":"Nesta semana o corpo se integra. Começamos aprendendo a levantar do chão com consciência — um movimento do dia a dia que merece ser suave.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Comece deitada de costas, joelhos dobrados. Tenha espaço livre ao redor."},{"tipo":"passo","titulo":"Rolar para o lado","conteudo":"Como fazer: Vire a cabeça para um lado e deixe o corpo rolar inteiro para esse lado, como um tronco. Chegue de lado, joelhos dobrados.\nRespiração: Solte o ar ao rolar.\nRepetições: 2 vezes para cada lado.\nVocê deve sentir: o corpo se movendo em bloco, sem “se puxar” pelo pescoço.\n⚠️ Sinal de parar: use as mãos para ajudar; nada de esforço no pescoço."},{"tipo":"passo","titulo":"Subir para sentada e para de pé","conteudo":"Como fazer: De lado, apoie as mãos no chão e empurre para sentar. Depois leve um pé à frente e use as mãos nas coxas para subir devagar até em pé.\nRespiração: Expire nos momentos de esforço (empurrar, subir).\nRepetições: 3 subidas conscientes.\nVocê deve sentir: as pernas trabalhando, o movimento organizado do chão ao pé.\n⚠️ Sinal de parar: apoie-se numa cadeira firme se precisar; sem pressa."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Em pé, sinta os pés no chão e a coluna longa. Você acabou de transformar um gesto automático em prática."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"A forma como você levanta do chão ou da cama diz muito. Fazer devagar poupa a lombar todos os dias."}]}}},{"numero":2,"titulo":"Terça","aula":{"titulo":"Coluna que desenrola","duracao":20,"conteudo":{"intro":"O roll down: descer a coluna vértebra por vértebra e voltar. Um dos movimentos mais gostosos para soltar as costas em pé.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, pés na largura do quadril, joelhos leeeves (nunca travados). Braços soltos."},{"tipo":"passo","titulo":"Desenrolar para baixo","conteudo":"Como fazer: Deixe o queixo cair em direção ao peito e vá descendo a coluna aos poucos, como se desenrolasse osso por osso, o tronco pendendo para frente. Desça só até onde é confortável, joelhos macios.\nRespiração: Solte o ar durante toda a descida.\nRepetições: 4 vezes.\nVocê deve sentir: as costas se abrindo e a cabeça pesada pendurando.\n⚠️ Sinal de parar: não force as mãos ao chão; a amplitude é sua. Tontura ao voltar? Suba mais devagar."},{"tipo":"passo","titulo":"Enrolar para cima","conteudo":"Como fazer: Para voltar, comece pela base da coluna, empilhando vértebra por vértebra, e deixe a cabeça ser a última a subir.\nRespiração: Inspire subindo, lentamente.\nRepetições: a cada roll down, siga direto para o roll up.\nVocê deve sentir: a coluna se “empilhando” e o corpo ficando alto de novo.\n⚠️ Sinal de parar: se ficar tonta, pause a meio caminho e respire."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Em pé, olhos fechados, sinta a coluna longa e as costas soltas. Perceba a respiração mais tranquila."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Joelhos “moles” aqui não são preguiça — são proteção. Travar os joelhos joga toda a carga na lombar."}]}}},{"numero":3,"titulo":"Quarta","aula":{"titulo":"Braços que respiram","duracao":20,"conteudo":{"intro":"Um fluxo suave de braços em pé, guiado pela respiração. Abre o peito, solta os ombros e acalma a mente.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, pés na largura do quadril, joelhos macios, braços ao lado do corpo."},{"tipo":"passo","titulo":"Braços que sobem com o ar","conteudo":"Como fazer: Ao inspirar, suba os braços pelos lados até acima da cabeça (ou até onde é confortável). Ao soltar, desça-os pela frente, devagar.\nRespiração: Inspire subindo, expire descendo.\nRepetições: 6 vezes.\nVocê deve sentir: o ar “levantando” os braços e o peito abrindo no alto.\n⚠️ Sinal de parar: se os ombros subirem demais ou o pescoço tensionar, suba menos."},{"tipo":"passo","titulo":"Colher água","conteudo":"Como fazer: Incline levemente o tronco à frente (joelhos macios) e faça o gesto de “colher água” com as mãos, trazendo-as para o peito ao subir o tronco, como se oferecesse algo a si mesma.\nRespiração: Inspire ao recolher, expire ao soltar as mãos para baixo.\nRepetições: 5 vezes, num fluxo contínuo.\nVocê deve sentir: o movimento inteiro conectado — pernas, tronco, braços, respiração.\n⚠️ Sinal de parar: mantenha os joelhos macios e a lombar longa."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Pare em pé, braços ao lado do corpo, e sinta o efeito: peito aberto, ombros baixos, respiração ampla."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Quando a respiração conduz o movimento, o exercício vira quase uma meditação em pé. Repare como a cabeça esvazia."}]}}},{"numero":4,"titulo":"Quinta","aula":{"titulo":"Equilíbrio calmo (prática leve)","duracao":18,"conteudo":{"intro":"Dia mais tranquilo para brincar com o peso do corpo e o equilíbrio — sem desafio, só percepção. Suave, e conta como constância.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, perto de uma parede ou cadeira para apoio, pés na largura do quadril."},{"tipo":"passo","titulo":"Transferir o peso","conteudo":"Como fazer: Passe o peso lentamente para o pé direito, sentindo-o afundar no chão; depois para o esquerdo. Como um pêndulo devagar.\nRespiração: Respiração natural e contínua.\nRepetições: 8 transferências.\nVocê deve sentir: os pés “lendo” o chão e o corpo se organizando sozinho.\n⚠️ Sinal de parar: mantenha a mão perto do apoio; segure se precisar."},{"tipo":"passo","titulo":"Nas pontas, devagar","conteudo":"Como fazer: Suba levemente nas pontas dos pés e desça bem devagar, controlando a descida. Use o apoio à vontade.\nRespiração: Inspire subindo, expire descendo lentamente.\nRepetições: 5 vezes.\nVocê deve sentir: as panturrilhas trabalhando e os tornozelos ganhando firmeza.\n⚠️ Sinal de parar: se o equilíbrio oscilar, mantenha a mão no apoio o tempo todo."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Fique um instante com os pés inteiros no chão, sentindo-se firme e presente."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Equilíbrio não é dom, é prática. Cada vez que você o treina com calma, o corpo fica mais seguro no dia a dia."}]}}},{"numero":5,"titulo":"Sexta","aula":{"titulo":"Quadril em pé","duracao":20,"conteudo":{"intro":"Levamos a soltura do quadril para a posição em pé, com círculos lentos e um agachamento suave e apoiado.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, pés um pouco mais afastados que o quadril, joelhos macios. Mãos na cintura ou perto de um apoio."},{"tipo":"passo","titulo":"Círculos de quadril","conteudo":"Como fazer: Desenhe círculos lentos com o quadril, como se movesse um bambolê imaginário devagar. Faça num sentido e depois no outro.\nRespiração: Respiração livre e contínua.\nRepetições: 5 círculos para cada lado.\nVocê deve sentir: o quadril se soltando e a lombar acompanhando com leveza.\n⚠️ Sinal de parar: círculos pequenos; nada de forçar a lombar."},{"tipo":"passo","titulo":"Agachamento apoiado","conteudo":"Como fazer: De frente para uma cadeira ou bancada, segure levemente para apoio. Dobre os joelhos e leve o quadril para trás e para baixo, só até a metade do caminho, e volte.\nRespiração: Inspire ao descer, expire ao subir.\nRepetições: 6 vezes suaves.\nVocê deve sentir: as coxas e o quadril trabalhando, os joelhos alinhados com os pés.\n⚠️ Sinal de parar: desça só até onde é confortável; joelho nunca deve doer."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Fique em pé, solte os braços e sinta a base do corpo mais acordada e firme."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Sentar e levantar da cadeira o dia todo já é um agachamento. Fazer com consciência algumas vezes melhora o gesto inteiro."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Coluna em espiral","duracao":20,"conteudo":{"intro":"Rotações suaves em pé que integram coluna, ombros e quadril. A espiral é um movimento muito natural e libertador.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, pés na largura do quadril, joelhos macios, braços soltos."},{"tipo":"passo","titulo":"Girar como um pião lento","conteudo":"Como fazer: Deixe os braços soltos e gire o tronco suavemente de um lado ao outro, permitindo que os braços “batam” de leve no corpo. Os calcanhares podem se soltar do chão levemente.\nRespiração: Respiração livre, solta.\nRepetições: 10 giros suaves, alternando os lados.\nVocê deve sentir: a coluna torcendo com leveza e os ombros balançando soltos.\n⚠️ Sinal de parar: sem forçar a torção no final; deixe a inércia levar."},{"tipo":"passo","titulo":"Espiral consciente","conteudo":"Como fazer: Agora mais devagar: ao inspirar volte ao centro; ao soltar, gire para um lado levando o olhar por cima do ombro. Alterne.\nRespiração: Expire girando, inspire ao centro.\nRepetições: 4 para cada lado.\nVocê deve sentir: a diferença entre a torção solta (antes) e a torção consciente (agora).\n⚠️ Sinal de parar: pare se sentir tontura; retome quando passar."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Volte ao centro, respire fundo e sinta a coluna mais móvel dos quadris aos ombros."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"A coluna gira melhor quando o pescoço não “puxa” o movimento. Deixe o olhar acompanhar, não liderar."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"Fluir devagar (prática leve)","duracao":18,"conteudo":{"intro":"Uma mini-sequência restaurativa juntando o que a semana trouxe: desenrolar, braços e respiração. Leve, fluida, gostosa.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, com espaço, joelhos macios."},{"tipo":"passo","titulo":"Sequência do fim de semana","conteudo":"Como fazer: Encadeie devagar: braços sobem com a inspiração → desenrole a coluna para baixo soltando o ar → pause pendurada por uma respiração → enrole de volta para cima → braços descem pela frente.\nRespiração: Deixe a respiração marcar o ritmo de cada parte.\nRepetições: 4 rodadas lentas, cada uma mais fluida.\nVocê deve sentir: as partes se conectando num único movimento contínuo.\n⚠️ Sinal de parar: sem pressa entre as fases; se tontear ao subir, suba mais devagar."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Fique em pé, olhos fechados, e sinta o corpo inteiro reunido e calmo. Três semanas — você está mais presente no próprio corpo."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Uma sequência só sua já está nascendo. Na próxima semana você vai montar a que mais combina com seus dias."}]}}}]},{"numero":4,"titulo":"Semana 4 — Prática consolidada","dias":[{"numero":1,"titulo":"Segunda","aula":{"titulo":"Sua sequência da manhã","duracao":22,"conteudo":{"intro":"Uma sequência completa para começar o dia acordando o corpo com gentileza. Guarde esta — ela pode virar seu ritual matinal.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Comece deitada na cama ou no tapete, ao acordar. Depois vamos para sentada e em pé. Tenha um apoio por perto."},{"tipo":"passo","titulo":"Acordar deitada","conteudo":"Como fazer: Espreguice o corpo inteiro (pandiculação): estique braços e pernas em direções opostas, sustente e solte. Depois faça 6 balanços de pelve.\nRespiração: Inspire ao esticar, solte ao relaxar.\nRepetições: 2 espreguiçadas + 6 balanços.\nVocê deve sentir: o corpo saindo do modo “dormindo” com prazer.\n⚠️ Sinal de parar: movimentos generosos, mas sem cãibra; se vier, relaxe."},{"tipo":"passo","titulo":"Sentar e abrir","conteudo":"Como fazer: Role para o lado, sente-se. Faça 6 “leques” de braços (Dia 6) abrindo o peito e 4 rotações de cabeça (Dia 5).\nRespiração: Respiração conduzindo cada abertura.\nRepetições: como descrito.\nVocê deve sentir: o tronco e o pescoço se soltando da rigidez matinal.\n⚠️ Sinal de parar: devagar — de manhã o corpo está mais “curto”."},{"tipo":"passo","titulo":"Levantar e crescer","conteudo":"Como fazer: Suba para em pé com consciência (Dia 15). Faça 4 subidas de braços com a respiração e termine com um roll down suave.\nRespiração: Inspire subindo os braços, expire desenrolando.\nRepetições: como descrito.\nVocê deve sentir: o corpo desperto, aberto e pronto para o dia.\n⚠️ Sinal de parar: joelhos macios no roll down; suba sem pressa."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Em pé, três respirações longas. Repare como é diferente começar o dia assim."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Fazer isso antes de pegar o celular muda o tom do dia inteiro. Experimente por alguns dias e sinta."}]}}},{"numero":2,"titulo":"Terça","aula":{"titulo":"Soltar o dia","duracao":22,"conteudo":{"intro":"Sequência para o fim do dia: descarregar a tensão acumulada no pescoço, ombros e lombar antes de descansar.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Comece sentada numa cadeira; depois vamos ao chão. Luz baixa ajuda a desacelerar."},{"tipo":"passo","titulo":"Descarregar de cima","conteudo":"Como fazer: Sentada: 4 espreguiçadas de ombros (Dia 8), a meia-lua do queixo (Dia 9) e o auto-abraço (Dia 6).\nRespiração: Expirações longas em cada soltura.\nRepetições: como descrito.\nVocê deve sentir: o peso do dia saindo dos ombros e do pescoço.\n⚠️ Sinal de parar: nada de forçar; hoje é para soltar, não conquistar."},{"tipo":"passo","titulo":"Soltar a lombar","conteudo":"Como fazer: No chão: gato e vaca (Dia 10), abraço de joelhos (Dia 13) e torção suave (Dia 14).\nRespiração: Respiração para dentro das costas.\nRepetições: como descrito.\nVocê deve sentir: a lombar e o quadril se abrindo e descansando.\n⚠️ Sinal de parar: se algo incomodar, pule aquele movimento e siga."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Termine deitada, pernas estendidas, por um minuto. Corpo mais leve para dormir."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Levar tensão para a cama atrapalha o sono. Cinco minutos de soltura à noite valem por horas de rolar na cama."}]}}},{"numero":3,"titulo":"Quarta","aula":{"titulo":"Corpo inteiro","duracao":25,"conteudo":{"intro":"A sequência mais completa do protocolo, integrando as quatro semanas. Reserve um tempinho a mais e aproveite cada parte.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Espaço livre, tapete, e um apoio por perto. Comece em pé."},{"tipo":"passo","titulo":"Aquecer e desenrolar","conteudo":"Como fazer: Em pé: braços que respiram (Dia 17), espiral consciente (Dia 20) e roll down/roll up (Dia 16).\nRespiração: Respiração marcando cada fase.\nRepetições: 2 rodadas de cada.\nVocê deve sentir: o corpo aquecendo e a coluna ganhando fluidez.\n⚠️ Sinal de parar: joelhos macios; suba devagar dos roll downs."},{"tipo":"passo","titulo":"Base firme","conteudo":"Como fazer: Círculos de quadril (Dia 19) e agachamento apoiado (Dia 19), depois transferência de peso (Dia 18).\nRespiração: Inspire descendo, expire subindo.\nRepetições: como descrito.\nVocê deve sentir: a base do corpo acordada e firme.\n⚠️ Sinal de parar: amplitude confortável nos joelhos."},{"tipo":"passo","titulo":"Voltar ao chão e fechar","conteudo":"Como fazer: Vá ao chão: gato e vaca, joelhos que balançam (Dia 12) e torção suave. Termine deitada, respirando.\nRespiração: Expiração sempre mais longa.\nRepetições: como descrito.\nVocê deve sentir: o corpo inteiro reunido, solto e presente.\n⚠️ Sinal de parar: respeite os limites do dia; nem todo dia é igual."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Fique deitada em silêncio por um minuto ao final. Sinta o quanto você já consegue."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Repare: movimentos que no Dia 1 pareciam estranhos agora são familiares. Isso é o corpo reaprendendo a se mover."}]}}},{"numero":4,"titulo":"Quinta","aula":{"titulo":"Recuperar (prática leve)","duracao":20,"conteudo":{"intro":"Depois de uma sequência intensa, um dia de recuperação com pernas apoiadas e respiração longa. Cuidar de descansar também é praticar.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Deitada com as pernas apoiadas numa cadeira ou parede (Dia 11). Cobertor se quiser."},{"tipo":"passo","titulo":"Descanso ativo","conteudo":"Como fazer: Pernas apoiadas, faça a varredura do corpo (Dia 4), soltando região por região. Depois só respire.\nRespiração: Expiração bem longa, como um suspiro.\nRepetições: 5 a 6 minutos.\nVocê deve sentir: o sistema inteiro desacelerando.\n⚠️ Sinal de parar: saia da posição se formigar demais."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Role para o lado, descanse e levante-se sem pressa. Recuperada e pronta para os últimos dias."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Progresso não acontece só no esforço — acontece no descanso, quando o corpo assimila o que aprendeu."}]}}},{"numero":5,"titulo":"Sexta","aula":{"titulo":"Respiração e movimento","duracao":22,"conteudo":{"intro":"Hoje a estrela é a respiração conduzindo tudo. Uma prática fluida em que cada movimento nasce de um ciclo respiratório.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Em pé, com espaço. Comece só observando a respiração por 3 ciclos."},{"tipo":"passo","titulo":"Movimento nascido do ar","conteudo":"Como fazer: Deixe cada inspiração “abrir” um movimento (subir braços, crescer, abrir peito) e cada expiração “soltar” (descer, arredondar, girar). Não conte movimentos — deixe a respiração escolher.\nRespiração: A respiração comanda; o corpo obedece devagar.\nRepetições: 5 a 7 minutos de fluxo livre.\nVocê deve sentir: o corpo se movendo sozinho, guiado pelo ar, sem “decidir”.\n⚠️ Sinal de parar: se a respiração acelerar ou faltar ar, pare e normalize."},{"tipo":"passo","titulo":"Aquietar","conteudo":"Como fazer: Aos poucos, deixe os movimentos ficarem menores até parar em pé, quieta, só respirando.\nRespiração: Respiração natural, longa.\nRepetições: 1 minuto.\nVocê deve sentir: a calma que fica depois do movimento consciente.\n⚠️ Sinal de parar: nenhum — é o pouso."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Abra os olhos devagar. Repare como corpo e respiração estão do mesmo lado agora."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Essa conexão respiração-movimento é o coração do somático. Quando ela acontece, o “exercício” some e vira presença."}]}}},{"numero":6,"titulo":"Sábado","aula":{"titulo":"Minha prática","duracao":22,"conteudo":{"intro":"Hoje você monta a sua própria sequência. Já tem repertório para isso — vamos te guiar a escolher o que o seu corpo mais pede.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Espaço livre. Pense: qual região sua mais pede cuidado hoje? Pescoço/ombros? Lombar/quadril? Ou o corpo todo?"},{"tipo":"passo","titulo":"Escolha um começo","conteudo":"Como fazer: Comece por um movimento de percepção e respiração (Dia 1, 2 ou 4). Dê-se 2 a 3 minutos só para chegar.\nRespiração: Respiração tranquila.\nRepetições: 2 a 3 minutos.\nVocê deve sentir: a diferença entre “começar acelerada” e “começar chegando”.\n⚠️ Sinal de parar: sem pular a chegada; ela prepara o resto."},{"tipo":"passo","titulo":"Escolha o miolo","conteudo":"Como fazer: Escolha 2 ou 3 movimentos das semanas 2 e 3 para a região que pediu atenção. Faça cada um com calma.\nRespiração: Respiração conduzindo.\nRepetições: 10 a 12 minutos.\nVocê deve sentir: o corpo respondendo ao que VOCÊ escolheu — isso é autonomia.\n⚠️ Sinal de parar: se algum movimento não cair bem hoje, troque por outro."},{"tipo":"passo","titulo":"Escolha um fim","conteudo":"Como fazer: Termine com algo restaurativo (pernas apoiadas, torção suave ou abraço de joelhos) e respiração longa.\nRespiração: Expiração longa.\nRepetições: 3 a 4 minutos.\nVocê deve sentir: o fechamento que deixa o corpo em paz.\n⚠️ Sinal de parar: nenhum."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Você acabou de conduzir a própria prática. Esse é o objetivo dos 28 dias: você no comando do seu corpo."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"Guarde mentalmente (ou anote) a sequência que mais te fez bem hoje. Ela é o começo da sua prática para a vida."}]}}},{"numero":7,"titulo":"Domingo","aula":{"titulo":"Seguindo em frente","duracao":25,"conteudo":{"intro":"Último dia! Uma sequência completa de celebração e um mapa para você continuar depois. O protocolo termina, a prática fica.","blocos":[{"tipo":"texto","titulo":"Preparação","conteudo":"Espaço livre, tapete e um apoio. Comece em pé, com uma respiração de gratidão pelo caminho até aqui."},{"tipo":"passo","titulo":"A sequência da jornada","conteudo":"Como fazer: Encadeie com calma: braços que respiram → espiral → roll down/up → círculos de quadril → ao chão para gato e vaca → torção suave → deitada para fechar.\nRespiração: Respiração guiando tudo, sem pressa.\nRepetições: uma passagem inteira, saboreada.\nVocê deve sentir: o corpo que você conheceu ao longo de 28 dias, mais solto e presente.\n⚠️ Sinal de parar: respeite o dia; celebrar não é forçar."},{"tipo":"texto","titulo":"Como continuar depois dos 28 dias","conteudo":"Não precisa de fórmula: 10 a 20 minutos, 3 a 5 vezes por semana, já sustentam tudo o que você ganhou. Nos dias corridos, faça só a chegada e a respiração — vale. Volte a qualquer aula quando quiser; elas continuam aqui. E, principalmente: siga escutando o corpo. Ele agradece todos os dias."},{"tipo":"texto","titulo":"Para encerrar","conteudo":"Deite por um minuto ao final e reconheça: você apareceu 28 dias por você. Isso muda a relação com o próprio corpo — e ninguém tira de você."},{"tipo":"dica","titulo":"Dica do dia","conteudo":"O maior resultado não é físico: é saber que você é capaz de cuidar de si, um movimento de cada vez. Parabéns. 🤍"}]}}}]}]$weeks$::jsonb;
  v_sales      jsonb := $sales${"headline":"Reconecte com o seu corpo em 28 dias, no seu ritmo","subheadline":"Movimentos somáticos suaves inspirados no Pilates — sem academia, sem equipamento, sem pressa.","bullets":["Práticas guiadas de 10 a 25 minutos, dia a dia","Movimento lento e consciente para soltar a tensão do dia","Feito para quem está começando — respeitando os seus limites"],"cta_label":"QUERO O PROTOCOLO"}$sales$::jsonb;
  v_week       jsonb;
  v_dia        jsonb;
begin
  -- 1) Localiza o produto base (prioriza o slug alvo; depois os anteriores).
  select id into v_product_id
    from public.products
   where slug in ('ritual-do-tapetinho', 'pilates-somatico', 'caminhada-japonesa')
   order by case slug
           when 'ritual-do-tapetinho' then 0
           when 'pilates-somatico' then 1
           when 'caminhada-japonesa' then 2
           else 99 end
   limit 1;

  if v_product_id is null then
    raise exception 'Produto base nao encontrado (slugs: ritual-do-tapetinho, pilates-somatico, caminhada-japonesa). Nada foi alterado.';
  end if;

  -- 2) Atualiza o produto. NÃO toca em kiwify_product_id / kiwify_checkout_url.
  update public.products
     set nome      = $nome$Protocolo 28 Dias — Ritual do Tapetinho$nome$,
         slug      = 'ritual-do-tapetinho',
         descricao = $desc$Movimentos somáticos inspirados no Pilates: 28 dias de prática lenta e consciente para soltar tensão e reconectar com o corpo, no seu ritmo e sem equipamento.$desc$,
         sales_page = v_sales,
         ativo     = true
   where id = v_product_id;

  -- 3) Desativa programas antigos do produto (mantém o conteúdo no banco).
  update public.programs
     set ativo = false
   where product_id = v_product_id
     and slug <> 'ritual-do-tapetinho';

  -- 4) Cria/atualiza o programa novo (upsert por slug único).
  insert into public.programs
      (product_id, slug, nome, descricao, capa_url, duracao_semanas, ordem_exibicao, ativo)
  values
      (v_product_id, 'ritual-do-tapetinho',
       $pnome$Protocolo 28 Dias — Ritual do Tapetinho$pnome$,
       $pdesc$Prática somática progressiva de 4 semanas — movimento lento e consciente para aliviar tensão, respirar melhor e se reconectar com o corpo.$pdesc$,
       null, 4, 0, true)
  on conflict (slug) do update
     set product_id      = excluded.product_id,
         nome            = excluded.nome,
         descricao       = excluded.descricao,
         duracao_semanas = excluded.duracao_semanas,
         ordem_exibicao  = excluded.ordem_exibicao,
         ativo           = true
  returning id into v_program_id;

  -- (re)insere o conteúdo: apaga semanas do programa novo (cascade em
  -- days/lessons) e recria a partir do JSON. Não afeta o programa antigo.
  delete from public.program_weeks where program_id = v_program_id;

  for v_week in select * from jsonb_array_elements(v_weeks)
  loop
    insert into public.program_weeks (program_id, numero, titulo)
    values (v_program_id, (v_week->>'numero')::int, v_week->>'titulo')
    returning id into v_week_id;

    for v_dia in select * from jsonb_array_elements(v_week->'dias')
    loop
      insert into public.program_days (week_id, numero, titulo)
      values (v_week_id, (v_dia->>'numero')::int, v_dia->>'titulo')
      returning id into v_day_id;

      insert into public.lessons (day_id, titulo, tipo, panda_video_id, conteudo, duracao_min, ordem)
      values (
        v_day_id,
        v_dia->'aula'->>'titulo',
        'guia',
        null,
        v_dia->'aula'->'conteudo',
        (v_dia->'aula'->>'duracao')::int,
        0
      );
    end loop;
  end loop;

  raise notice 'OK: produto % atualizado; programa ritual-do-tapetinho % com % aulas.',
    v_product_id, v_program_id,
    (select count(*) from public.lessons l
       join public.program_days d on d.id = l.day_id
       join public.program_weeks w on w.id = d.week_id
      where w.program_id = v_program_id);
end
$migration$;

-- =====================================================================
-- VERIFICAÇÃO (rode e confira os resultados)
-- =====================================================================

-- Produto atualizado (kiwify_* devem permanecer os originais):
select slug, nome, ativo, kiwify_product_id, kiwify_checkout_url
  from public.products
 where slug = 'ritual-do-tapetinho';

-- Programas do produto: o antigo deve estar ativo=false, o novo ativo=true.
select p.slug, p.nome, p.ativo, p.ordem_exibicao
  from public.programs p
  join public.products pr on pr.id = p.product_id
 where pr.slug = 'ritual-do-tapetinho'
 order by p.ativo desc, p.slug;

-- Contagem de aulas do programa novo (esperado: 28).
select count(*) as total_aulas
  from public.lessons l
  join public.program_days d on d.id = l.day_id
  join public.program_weeks w on w.id = d.week_id
  join public.programs p on p.id = w.program_id
 where p.slug = 'ritual-do-tapetinho';

-- Aulas por semana (esperado: 7 em cada uma das 4 semanas).
select w.numero as semana, w.titulo, count(l.*) as aulas
  from public.program_weeks w
  join public.programs p on p.id = w.program_id
  join public.program_days d on d.week_id = w.id
  join public.lessons l on l.day_id = d.id
 where p.slug = 'ritual-do-tapetinho'
 group by w.numero, w.titulo
 order by w.numero;
